-- XACT_ABORT is OFF by default
BEGIN TRANSACTION;
UPDATE dbo.Wallets SET Balance -= 100 WHERE Id = 1;
UPDATE dbo.Wallets SET Balance += 100 WHERE Id = 2;
COMMIT;
-- Tested: Msg 547 on the credit, then COMMIT ran.
-- Mona 500 -> 400, Karim stays 950: 100 vanished

SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    UPDATE dbo.Wallets SET Balance -= 100 WHERE Id = 1;
    UPDATE dbo.Wallets SET Balance += 100 WHERE Id = 2;
    COMMIT;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
END CATCH;
-- Tested: Msg 547 reaches the caller, both balances unchanged

