using Microsoft.EntityFrameworkCore;

static async Task TransferAsync(
    WalletsDb db, int fromId, int toId, decimal amount)
{
    // Both statements in one transaction: both commit, or neither does
    await using var tx = await db.Database.BeginTransactionAsync();
    await db.Wallets.Where(w => w.Id == fromId).ExecuteUpdateAsync(
        s => s.SetProperty(w => w.Balance, w => w.Balance - amount));
    var credited = await db.Wallets.Where(w => w.Id == toId).ExecuteUpdateAsync(
        s => s.SetProperty(w => w.Balance, w => w.Balance + amount));

    // Matching zero rows isn't an error to the database: check it yourself
    if (credited != 1) throw new InvalidOperationException($"No wallet {toId}");
    await tx.CommitAsync(); // skipped on any exception: disposal rolls back
}
